#include <random>
#include <sstream>
#include <cassert>
#include <iostream>

int main() {
    using Engine = std::mt19937;
    Engine engine{42};
    Engine copy{42};
    assert(engine == copy);
    auto value = engine();
    assert(value >= Engine::min() && value <= Engine::max());
    engine.seed(42);
    engine.discard(3);
    for (int i = 0; i < 3; ++i) {
        (void)copy();
    }
    assert(engine == copy);

    std::stringstream saved;
    saved << engine;
    saved >> copy;
    assert(copy == engine);
    std::cout << "Checks passed\n";
}
